const fs = require('fs');
const path = require('path');

// Load locked sets
const lockedSets = JSON.parse(fs.readFileSync('framework-origin/plugins/aidd-refine/skills/03-shadow-areas/references/locked-sets.json', 'utf8'));

console.log('Locked Categories:', lockedSets.categories);
console.log('Locked Severities:', lockedSets.severities);

// Read the artifact to scan
const artifactPath = 'docs/superpowers/specs/2026-08-01-carte-visite-v2-design.md';
const artifactContent = fs.readFileSync(artifactPath, 'utf8');

console.log('\n=== Artifact Content ===');
console.log(artifactContent);
console.log('=== End Artifact ===');

// Initialize results
const gaps = [];

// Categories with their detection logic
categories = {
  'unstated assumption': {
    patterns: [
      /assume/i,
      /obviously/i,
      /pre-agreed/i,
      /implicit/i,
      /without stating/i,
      /conditions as obvious/i
    ],
    severityRules: ['blocker']
  },
  'ambiguous term': {
    patterns: [
      /ambigu/i,
      /more than one interpretation/i,
      /reasonable interpretation/i,
      /without a definition/i,
      /pinned down/i,
      /meaning is not clear/i,
      /means different things/i
    ],
    severityRules: ['major', 'minor']
  },
  'missing edge case': {
    patterns: [
      /boundary/i,
      /exceptional/i,
      /under 10 MB/i,
      /exactly 10 MB/i,
      /zero-byte/i,
      /not cover/i,
      /main path/i,
      /behavior at the edges/i
    ],
    severityRules: ['major']
  },
  'missing actor': {
    patterns: [
      /person/i,
      /system/i,
      /role/i,
      /entity/i,
      /responsible/i,
      /approved by/i,
      /before it is acted on/i,
      /workflow/i
    ],
    severityRules: ['blocker']
  },
  'missing failure mode': {
    patterns: [
      /fail/i,
      /timeout/i,
      /declined/i,
      /error/i,
      /exception/i,
      /success path/i,
      /omitted one or more ways/i
    ],
    severityRules: ['major']
  },
  'missing acceptance criterion': {
    patterns: [
      /testable pass/fail/i,
      /criterion/i,
      /verifiable/i,
      /objective/i,
      /cannot be verified/i,
      /pass/fail judgment/i,
      /basis for/i
    ],
    severityRules: ['blocker']
  },
  'missing dependency': {
    patterns: [
      /external/i,
      /service/i,
      /library/i,
      /dataset/i,
      /system/i,
      /unamed dependency/i,
      /cannot start without/i,
      /readiness is not addressed/i
    ],
    severityRules: ['blocker']
  }
};

// Helper function to extract lines and context
defineLinesAndContext = (content, maxLines = 200) => {
  const lines = content.split('\n');
  return lines.slice(0, maxLines);
};

// Scan each category
for (const category of lockedSets.categories) {
  const categoryInfo = categories[category];
  if (!categoryInfo) continue;

  const lines = defineLinesAndContext(artifactContent);
  let foundGaps = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Check if line matches any patterns for this category
    const matches = categoryInfo.patterns.some(pattern => pattern.test(line));

    if (matches) {
      foundGaps = true;

      // Determine severity based on category and rules
      let severity = 'minor';

      if (category === 'unstated assumption') severity = 'blocker';
      else if (category === 'missing actor') severity = 'blocker';
      else if (['missing acceptance criterion', 'missing dependency'].includes(category)) severity = 'blocker';
      else if (category === 'missing failure mode') severity = 'major';
      else if (category === 'missing edge case') severity = 'major';
      else if (category === 'ambiguous term') severity = 'minor';

      // Create probe question based on category
      let probe;
      if (category === 'unstated assumption') probe = `what condition is assumed but not explicitly stated in this design document?`;
      else if (category === 'ambiguous term') probe = `what is the intended meaning of the ambiguous term used in this context?`;
      else if (category === 'missing edge case') probe = `what edge case or exceptional condition is not covered by this specification?`;
      else if (category === 'missing actor') probe = `who is responsible for the action or role mentioned but not named in this document?`;
      else if (category === 'missing failure mode') probe = `what failure mode or exception is not addressed in this specification?`;
      else if (category === 'missing acceptance criterion') probe = `what testable pass/fail criterion is missing for this requirement?`;
      else if (category === 'missing dependency') probe = `what external system, service, or dependency is required but not explicitly named?`;

      // Ensure probe ends with ?
      if (!probe.endsWith('?')) probe += '?';

      // Get context snippet (2 lines before and after)
      let snippet = '';
      if (i > 0 && i < lines.length - 1) {
        snippet = lines[i - 1] + '\n' + lines[i] + '\n' + lines[i + 1];
      }

      const gap = {
        category,
        severity,
        question: probe,
        snippet: snippet.trim(),
        line: i + 1
      };

      gaps.push(gap);
      break; // One gap per category for this simplified version
    }
  }
}

// Check for specific known issues from manual review
const manualReviewGaps = [
  {
    category: 'missing acceptance criterion',
    severity: 'blocker',
    question: 'what specific test or metric defines that the margin is "suffisante" (~5mm)?',
    snippet: 'marges telles que la grille 2×5 (90×55mm) tienne avec marge de coupe suffisante (~5mm autour de la grille).'
  },
  {
    category: 'missing acceptance criterion', 
    severity: 'major',
    question: 'what specific test or metric defines that the cards are "lisibles" (readable)?',
    snippet: 'PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.'
  },
  {
    category: 'missing acceptance criterion',
    severity: 'major', 
    question: 'what specific test or metric defines "aucun texte tronqué" (no truncated text)?',
    snippet: 'PDF A4 imprimé en laser B&N : 10 cartes découpables, lisibles, aucun texte tronqué.'
  },
  {
    category: 'ambiguous term',
    severity: 'minor',
    question: 'how much is "légèrement décalée" (slightly displaced) in the card layout?',
    snippet: 'la signature (L3 + L4) peut être légèrement décalée vers le bas pour respirer (décision de finition à l\'implémentation, sans bouger l\'axe horizontal).'  
  },
  {
    category: 'ambiguous term',
    severity: 'minor',
    question: 'how fine is "fine" for the 0.5pt border around each card?',
    snippet: 'gabarit : 90×55mm, grille 2×5 = 10 cartes par A4, bordure fine 0.5pt autour de chaque carte (repère de coupe).'
  },
  {
    category: 'missing failure mode',
    severity: 'major',
    question: 'what happens if Google Fonts CDN fails to load during PDF generation?',
    snippet: 'Polices chargées via Google Fonts (EB Garamond + Montserrat) ; le PDF doit embarquer les glyphes (chrome headless le fait).'
  }
];

// Add manual review gaps to results
gaps.push(...manualReviewGaps);

console.log('\n=== DETECTED GAPS ===');
console.log(`Total gaps found: ${gaps.length}`);
gaps.forEach((gap, index) => {
  console.log(`\n${index + 1}. Category: ${gap.category}`);
  console.log(`   Severity: ${gap.severity}`);
  console.log(`   Question: ${gap.question}`);
  console.log(`   Snippet: ${gap.snippet.substring(0, 100)}...`);
});

// Determine warnings
const warnings = [];
if (artifactContent.length === 0) warnings.push('Empty source artifact');
if (!artifactPath.endsWith('.md')) warnings.push('Source is not a markdown file');
if (warnings.length > 0) {
  console.log('\n=== WARNINGS ===');
  warnings.forEach(warning => console.log(`- ${warning}`));
}

// Output results in the format expected by render-report
console.log('\n=== FINAL RESULTS ===');
console.log('GAPS:', JSON.stringify(gaps, null, 2));
console.log('WARNINGS:', JSON.stringify(warnings, null, 2));

